properties.query:
let baselineWindow = 24h;
let alertWindow = 15m;
let binSize = 5m;
let gateMultiplier = 2.0;
let floorBytes = 500000000.0;
let dynGate = toscalar(
    UAVExfilFlow_CL
    | where TimeGenerated > ago(baselineWindow)
    | where AssetType in ("imagery", "sar")
    | summarize SumBytes = sum(BytesTransferred) by UAVId, bin(TimeGenerated, binSize)
    | summarize gate = percentile(SumBytes, 99) * gateMultiplier
);
let volGate = max_of(dynGate, floorBytes);
UAVExfilFlow_CL
| where TimeGenerated > ago(alertWindow)
| where AssetType in ("imagery", "sar")
| summarize SumBytes = sum(BytesTransferred), FlowCount = count(), Operator = any(Operator), DestIp = any(DestIp)
    by UAVId, AssetType, TimeBin = bin(TimeGenerated, binSize)
| where SumBytes > volGate
| extend TriggerReason = strcat("대량유출_버스트_", tostring(toint(SumBytes/1000000)), "MB/5min_게이트_", tostring(toint(volGate/1000000)), "MB")
| extend Severity = "High"
| project TimeGenerated = TimeBin, UAVId, AssetType, SumBytes, FlowCount, Operator, DestIp, TriggerReason, Severity
| order by TimeGenerated desc
